/**
 * Checks the actual production assets generated by `npm run build`.
 * Run `npm run check:bundle`; the package script builds first so stale assets
 * cannot make this check pass. This complements the source-level contracts by
 * checking that important product strings and integration points survive the
 * Vite production pipeline.
 */
import { existsSync, readdirSync, readFileSync, statSync } from "node:fs";
import { fileURLToPath } from "node:url";
import path from "node:path";

const root = fileURLToPath(new URL("../", import.meta.url));
const assetDir = path.join(root, "dist", "assets");
if (!existsSync(assetDir)) {
  console.error("Production assets are missing; run `npm run build` first.");
  process.exit(1);
}

const assets = readdirSync(assetDir)
  .filter((name) => name.endsWith(".js"))
  .map((name) => path.join(assetDir, name));
if (assets.length === 0) {
  console.error("No production JavaScript asset was found in dist/assets.");
  process.exit(1);
}

const bundle = assets.map((file) => readFileSync(file, "utf8")).join("\n");
const sizeBytes = assets.reduce((total, file) => total + statSync(file).size, 0);
const sizeKib = (sizeBytes / 1024).toFixed(1);

const expectations = [
  ["visibility event name", "music-visibility"],
  ["visibility query command", "get_music_visibility"],
  ["UI text: 外观与窗口", "外观与窗口"],
  ["UI text: 常用句名称", "常用句名称"],
  ["UI text: 过滤非常规软件", "过滤非常规软件"],
  ["WindowSize label", "window-size-editor"],
];

let missing = 0;
console.log(`bundle: ${sizeKib} KiB`);
for (const [label, needle] of expectations) {
  const found = bundle.includes(needle);
  if (!found) missing += 1;
  console.log(`  ${found ? "ok  " : "MISS"} ${label}`);
}

// Sanity: the assets must be non-empty JavaScript, not an HTML fallback page.
if (bundle.trim().length === 0 || /<!doctype html/i.test(bundle.slice(0, 400))) {
  console.error("  MISS output does not look like JavaScript");
  missing += 1;
}

if (missing) {
  console.error(`\nbundle check FAILED (${missing} expectation(s) unmet)`);
  process.exit(1);
}
console.log(`\nbundle check PASSED: ${assets.length} JavaScript asset(s), ${sizeKib} KiB, ${expectations.length + 1} checks`);
